const items = $input.all();

// Default mock documents for registered prototype bidders
const MOCK_BIDDER_DOCS = {
  "ABC Technologies Pvt Ltd": [
    {
      document_id: "DOC-GST-001",
      document_type: "GST_CERTIFICATE",
      file_name: "gst_registration_certificate.pdf",
      mime_type: "application/pdf",
      file_size: 245678,
      sha256: "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
      pdf_readable: true,
      page_count: 2,
      metadata: {
        creation_date: "2024-01-10T10:00:00Z",
        modification_date: "2024-01-10T10:30:00Z",
        producer: "Adobe PDF Library 15.0",
        creator: "GSTN Portal"
      },
      ocr_text: "Government of India Form GST REG-06 Registration Certificate 27AABCU9603R1ZM ABC Technologies Pvt Ltd Active Verified"
    },
    {
      document_id: "DOC-PAN-001",
      document_type: "PAN_CARD",
      file_name: "pan_card_copy.pdf",
      mime_type: "application/pdf",
      file_size: 154200,
      sha256: "a1b2c3d4e5f60718293a4b5c6d7e8f901234567890abcdef1234567890abcdef",
      pdf_readable: true,
      page_count: 1,
      metadata: {
        creation_date: "2023-05-12T08:00:00Z",
        modification_date: "2023-05-12T08:00:00Z",
        producer: "Income Tax Department NSDL",
        creator: "CBDT"
      },
      ocr_text: "INCOME TAX DEPARTMENT GOVT OF INDIA Permanent Account Number AABCU9603R ABC Technologies Pvt Ltd"
    }
  ]
};

return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];

  const requestId = data.request_id || "REQ-FOR-DEMO";
  const tenderId = data.tender_id || "TENDER-FOR-DEMO";
  const bidderId = data.bidder_id || "BIDDER-FOR-DEMO";
  const bidderName = (data.bidder_name || "ABC Technologies Pvt Ltd").toString().trim();

  let docs = data.documents;

  // If documents not explicitly provided or empty, resolve from mock database
  if (!docs || !Array.isArray(docs) || docs.length === 0) {
    docs = MOCK_BIDDER_DOCS[bidderName] || [];
  }

  if (!Array.isArray(docs)) {
    errors.push("Field 'documents' must be an array");
    docs = [];
  }

  return {
    json: {
      request_id: requestId,
      tender_id: tenderId,
      bidder_id: bidderId,
      bidder_name: bidderName,
      documents: docs,
      valid_schema: errors.length === 0,
      validation_errors: errors,
      raw_input: data
    }
  };
});

const items = $input.all();

const ALLOWED_MIMES = new Set([
  'application/pdf',
  'image/jpeg',
  'image/jpg',
  'image/png'
]);

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const docs = data.documents || [];
  const inspectedDocs = [];
  const issues = [];

  docs.forEach((doc, idx) => {
    const docId = doc.document_id || `DOC-${idx + 1}`;
    const docType = doc.document_type || 'UNKNOWN';
    const fileName = doc.file_name || 'unnamed_file';
    const mime = (doc.mime_type || '').toLowerCase().trim();
    const size = doc.file_size;
    const isCorrupt = doc.corrupt === true || doc.is_corrupted === true || doc.pdf_readable === false || doc.unreadable === true;

    let mimeValid = true;
    let sizeValid = true;
    let readabilityValid = true;

    // 1. MIME Validation
    if (!mime || !ALLOWED_MIMES.has(mime)) {
      mimeValid = false;
      issues.push(`Document '${docId}' (${fileName}) has invalid or unsupported MIME type: '${mime || 'MISSING'}'`);
    }

    // 2. File Size Validation (Reject 0-byte or negative)
    if (size === undefined || size === null || typeof size !== 'number' || isNaN(size) || size <= 0) {
      sizeValid = false;
      issues.push(`Document '${docId}' (${fileName}) has invalid or zero file size: ${size} bytes`);
    }

    // 3. Corruption & Readability
    if (isCorrupt) {
      readabilityValid = false;
      issues.push(`Document '${docId}' (${fileName}) is corrupted or unreadable`);
    }

    inspectedDocs.push({
      ...doc,
      document_id: docId,
      document_type: docType,
      file_name: fileName,
      mime_valid: mimeValid,
      size_valid: sizeValid,
      readability_valid: readabilityValid
    });
  });

  return {
    json: {
      ...data,
      documents: inspectedDocs,
      integrity_issues: issues
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const docs = data.documents || [];
  const metadataIssues = [];

  const inspectedDocs = docs.map(doc => {
    const meta = doc.metadata || {};
    let metadataConsistent = true;

    if (meta.creation_date && meta.modification_date) {
      const created = new Date(meta.creation_date).getTime();
      const modified = new Date(meta.modification_date).getTime();

      if (isNaN(created) || isNaN(modified)) {
        metadataConsistent = false;
        metadataIssues.push(`Document '${doc.document_id}' contains unparseable metadata dates`);
      } else if (modified < created) {
        metadataConsistent = false;
        metadataIssues.push(`Document '${doc.document_id}' metadata anomaly: modification date (${meta.modification_date}) is earlier than creation date (${meta.creation_date})`);
      }
    }

    // Page count validation if provided
    let pageCountValid = true;
    if (doc.page_count !== undefined) {
      if (typeof doc.page_count !== 'number' || doc.page_count <= 0) {
        pageCountValid = false;
        metadataConsistent = false;
        metadataIssues.push(`Document '${doc.document_id}' has invalid page count: ${doc.page_count}`);
      }
    }

    return {
      ...doc,
      metadata_consistent: metadataConsistent,
      page_count_valid: pageCountValid
    };
  });

  return {
    json: {
      ...data,
      documents: inspectedDocs,
      metadata_issues: metadataIssues
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const docs = data.documents || [];
  const ocrIssues = [];

  const inspectedDocs = docs.map(doc => {
    const text = doc.ocr_text !== undefined ? doc.ocr_text : (doc.text_content !== undefined ? doc.text_content : null);
    let ocrPresent = true;
    let contentConsistent = true;

    // 1. Text presence check (only when text property is provided or expected)
    if (text !== null) {
      if (typeof text !== 'string' || text.trim().length === 0) {
        ocrPresent = false;
        ocrIssues.push(`Document '${doc.document_id}' (${doc.file_name}): OCR text is empty or missing`);
      } else if (text.trim().length < 20) {
        ocrPresent = false;
        ocrIssues.push(`Document '${doc.document_id}' (${doc.file_name}): Extracted OCR text is abnormally short (${text.trim().length} chars)`);
      }
    }

    // 2. Document type consistency check
    if (text && typeof text === 'string') {
      const upperText = text.toUpperCase();
      const docType = (doc.document_type || '').toUpperCase();

      if (docType === 'GST_CERTIFICATE') {
        const hasGstKeywords = upperText.includes('GST') || upperText.includes('TAX') || upperText.includes('REGISTRATION');
        const isStrictlyPanOnly = upperText.includes('PERMANENT ACCOUNT NUMBER') && !hasGstKeywords;
        if (isStrictlyPanOnly) {
          contentConsistent = false;
          ocrIssues.push(`Document '${doc.document_id}' type mismatch: Classified as GST_CERTIFICATE but content indicates PAN_CARD`);
        }
      } else if (docType === 'PAN_CARD') {
        const hasPanKeywords = upperText.includes('PAN') || upperText.includes('INCOME TAX') || upperText.includes('ACCOUNT NUMBER');
        const isStrictlyGstOnly = upperText.includes('GSTIN') && !hasPanKeywords;
        if (isStrictlyGstOnly) {
          contentConsistent = false;
          ocrIssues.push(`Document '${doc.document_id}' type mismatch: Classified as PAN_CARD but content indicates GST_CERTIFICATE`);
        }
      }
    }

    return {
      ...doc,
      ocr_present: ocrPresent,
      content_consistent: contentConsistent
    };
  });

  return {
    json: {
      ...data,
      documents: inspectedDocs,
      ocr_issues: ocrIssues
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const docs = data.documents || [];
  const duplicateIssues = [];

  const seenHashes = new Map();
  const seenIds = new Set();

  let duplicateDetected = false;

  docs.forEach(doc => {
    // Check duplicate document ID
    if (seenIds.has(doc.document_id)) {
      duplicateDetected = true;
      duplicateIssues.push(`Duplicate document ID detected: '${doc.document_id}'`);
    } else {
      seenIds.add(doc.document_id);
    }

    // Check SHA-256 duplicate content across distinct documents
    if (doc.sha256) {
      const hash = doc.sha256.trim().toLowerCase();
      if (seenHashes.has(hash)) {
        duplicateDetected = true;
        duplicateIssues.push(`Duplicate document content detected: Document '${doc.document_id}' has identical SHA-256 hash as '${seenHashes.get(hash)}' (${hash.substring(0, 16)}...)`);
      } else {
        seenHashes.set(hash, doc.document_id);
      }
    }
  });

  return {
    json: {
      ...data,
      duplicate_detected: duplicateDetected,
      duplicate_issues: duplicateIssues
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  let status = "VERIFIED";
  let confidence = 0.98;
  let riskLevel = "LOW";
  const allIssues = [];

  if (!data.valid_schema) {
    status = "ERROR";
    confidence = 0.0;
    riskLevel = "HIGH";
    allIssues.push(...(data.validation_errors || ["Invalid document input structure"]));
  } else {
    const docs = data.documents || [];
    const integrityIssues = data.integrity_issues || [];
    const metaIssues = data.metadata_issues || [];
    const ocrIssues = data.ocr_issues || [];
    const dupIssues = data.duplicate_issues || [];

    allIssues.push(...integrityIssues, ...metaIssues, ...ocrIssues, ...dupIssues);

    if (docs.length === 0) {
      status = "NOT_VERIFIED";
      confidence = 0.90;
      riskLevel = "MEDIUM";
      allIssues.push("No bid documents submitted for forensic verification");
    } else if (allIssues.length > 0) {
      status = "NOT_VERIFIED";
      confidence = 0.98;
      riskLevel = "HIGH";
    } else {
      status = "VERIFIED";
      confidence = 0.99;
      riskLevel = "LOW";
    }
  }

  const docs = data.documents || [];
  const integritySummary = {
    mime_valid: docs.every(d => d.mime_valid !== false),
    file_size_valid: docs.every(d => d.size_valid !== false),
    pdf_readable: docs.every(d => d.readability_valid !== false),
    ocr_text_present: docs.every(d => d.ocr_present !== false),
    metadata_consistent: docs.every(d => d.metadata_consistent !== false),
    hash_valid: true,
    duplicate_detected: data.duplicate_detected || false,
    document_type_consistent: docs.every(d => d.content_consistent !== false)
  };

  return {
    json: {
      agent: "DOCUMENT_FORENSICS_AGENT",
      status,
      confidence,
      evidence: {
        documents_analyzed: docs.length,
        document_ids: docs.map(d => d.document_id),
        integrity_checks: integritySummary,
        findings: allIssues,
        registry_source: "DOCUMENT_FORENSICS_ENGINE"
      },
      issues: allIssues,
      risk_level: riskLevel,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: item.json
}));

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "DOCUMENT_FORENSICS_AGENT",
    status: "ERROR",
    confidence: 0.0,
    evidence: {
      error: "Document forensics agent encountered an unexpected execution failure",
      fallback_mode: true
    },
    issues: ["Document forensics agent failed unexpectedly"],
    risk_level: "HIGH",
    timestamp: new Date().toISOString()
  }
}));
